export const EXAMPLES = "# Example parts\n\nReal scripts from Parasocial's example documents.\n\n## examples/bracket/studios/bracket.ts\n\n```ts\nimport { part, param, sketch, plane, mm } from \"parasocial\";\n\nexport const name = \"Bracket\";\n\nexport default part(\"Bracket\", ({ color }) => {\n  const t = param(\"thickness\", 3, { min: 1, max: 10, unit: mm, step: 0.5 });\n  const w = param(\"width\", 40, { unit: mm });\n\n  const base = sketch(plane.XY)\n    .rect(w, 25, { center: true, tag: \"outline\" })\n    .circle([0, 0], 4, { tag: \"bore\" })\n    .extrude(t, { tag: \"base\" });\n\n  return base\n    .fillet(base.edges(\"base.side\").parallelTo(\"Z\"), 2, { tag: \"corners\" })\n    .chamfer(base.edges(\"base.cap.end & bore\"), 0.5)\n    .color(color.auto());\n});\n```\n\n## examples/enclosure/studios/enclosure.ts\n\n```ts\nimport { part, param, sketch, plane, mm } from \"parasocial\";\n\nexport const name = \"Enclosure\";\n\n// Body and lid share one footprint, so they live in one studio: part ids `enclosure` and `enclosure:lid`.\nconst CORNER = 6;\nconst CLEARANCE = 0.2;\n\n/** The footprint both halves are built from. Called inside each part, so each gets its own overridable params. */\nfunction footprint() {\n  return {\n    w: param(\"width\", 80, { min: 30, max: 200, unit: mm }),\n    d: param(\"depth\", 50, { min: 30, max: 200, unit: mm }),\n    wall: param(\"wall\", 2, { min: 1, max: 5, unit: mm, step: 0.2 }),\n  };\n}\n\nexport default part(\"Body\", ({ color }) => {\n  const { w, d, wall } = footprint();\n  const h = param(\"height\", 30, { min: 10, max: 120, unit: mm });\n\n  const shell = sketch(plane.XY).rect(w, d, { tag: \"outer\" }).extrude(h, { tag: \"block\" });\n  const rounded = shell.fillet(shell.edges(\"block.side\").parallelTo(\"Z\"), CORNER, { tag: \"corners\" });\n  const cavity = sketch(plane.XY.offset(wall))\n    .rect(w - 2 * wall, d - 2 * wall, { tag: \"inner\" })\n    .extrude(h, { tag: \"cavity\" });\n  const hollow = rounded.subtract(cavity, { tag: \"hollow\" });\n\n  // cable port on the front wall\n  const port = sketch(plane.XZ.offset(d / 2 + 1))\n    .slot([-8, h / 2], [8, h / 2], 6, { tag: \"port\" })\n    .extrude(wall + 2, { tag: \"portCut\" });\n  return hollow\n    .subtract(port, { tag: \"portHole\" })\n    .fillet(hollow.edges(\"cap.start & corners\"), 1.5, { tag: \"footRound\" })\n    .color(color.auto())\n    .material(\"petg\");\n});\n\nexport const lid = part(\"Lid\", ({ color }) => {\n  const { w, d, wall } = footprint();\n  const t = param(\"thickness\", 2.5, { min: 1, max: 6, unit: mm, step: 0.1 });\n  const lip = param(\"lip\", 3, { min: 1, max: 8, unit: mm });\n\n  const plate = sketch(plane.XY).rect(w, d, { tag: \"plate\" }).extrude(t, { tag: \"top\" });\n  const lidPlate = plate.fillet(plate.edges(\"top.side\").parallelTo(\"Z\"), CORNER, { tag: \"corners\" });\n  const ring = sketch(plane.XY.offset(-lip))\n    .rect(w - 2 * wall - 2 * CLEARANCE, d - 2 * wall - 2 * CLEARANCE, { tag: \"lipOuter\" })\n    .rect(w - 4 * wall, d - 4 * wall, { tag: \"lipInner\" })\n    .extrude(lip, { tag: \"lip\" });\n  return lidPlate\n    .union(ring, { tag: \"joined\" })\n    .chamfer(lidPlate.edges(\"top.cap.end & corners\"), 0.6, { tag: \"topEdge\" })\n    .translate([0, 0, 40])\n    // clear PETG: the body and its port show through the lid\n    .color(color.auto())\n    .appearance({ opacity: 0.45, roughness: 0.15 })\n    .material(\"petg\");\n});\n```\n\n## examples/enclosure/studios/mount.ts\n\n```ts\nimport { part, param, sketch, plane, mm } from \"parasocial\";\n\nexport const name = \"Wall mount\";\n\n// A separate component, so a separate studio: the wall plate the enclosure sits on (part id `mount`).\nexport default part(\"Wall mount\", ({ color }) => {\n  const w = param(\"width\", 110, { min: 40, max: 250, unit: mm });\n  const d = param(\"depth\", 60, { min: 30, max: 200, unit: mm });\n  const t = param(\"thickness\", 4, { min: 2, max: 10, unit: mm, step: 0.5 });\n  const screw = param(\"screw\", 4.5, { min: 2, max: 8, unit: mm, step: 0.1 });\n\n  const plate = sketch(plane.XY.offset(-t)).rect(w, d, { tag: \"edge\", fillet: 4 }).extrude(t, { tag: \"plate\" });\n\n  // a keyhole at each end, to hang the plate on two wall screws\n  const x = w / 2 - 10;\n  const below = plane.XY.offset(-t - 1);\n  const head = sketch(below).circle([x, 6], screw, { tag: \"head\" }).extrude(t + 2, { tag: \"head\" });\n  const slot = sketch(below).slot([x, 6], [x, -8], screw, { tag: \"slot\" }).extrude(t + 2, { tag: \"slot\" });\n  const keyholes = head.union(slot, { tag: \"keyhole\" }).mirror(\"YZ\", { union: true, tag: \"keyholes\" });\n  const cut = plate.subtract(keyholes, { tag: \"cut\" });\n  return cut\n    .chamfer(cut.edges(\"plate.cap.end & edge\"), 0.8, { tag: \"topEdge\" })\n    .color(color.auto())\n    .material(\"petg\");\n});\n```\n\n## examples/flange/lib/holes.ts\n\n```ts\nimport { cylinder, type Solid } from \"parasocial\";\n\n/** `count` through-holes of `diameter` on a circle of `radius`, as one tool body. */\nexport function boltCircle(count: number, radius: number, diameter: number, height: number): Solid {\n  const hole = cylinder(diameter / 2, height + 2, { at: [radius, 0, -1], tag: \"bolt\" });\n  return hole.circularPattern(count, { tag: \"bolts\" });\n}\n```\n\n## examples/flange/studios/flange.ts\n\n```ts\nimport { part, param, sketch, plane, mm } from \"parasocial\";\nimport { boltCircle } from \"../lib/holes\";\n\nexport const name = \"Flange\";\n\nexport default part(\"Flange\", ({ color }) => {\n  const od = param(\"outerDiameter\", 90, { min: 40, max: 200, unit: mm });\n  const bore = param(\"bore\", 30, { min: 5, max: 80, unit: mm });\n  const t = param(\"thickness\", 8, { min: 3, max: 30, unit: mm, step: 0.5 });\n  const hub = param(\"hubHeight\", 14, { min: 0, max: 60, unit: mm });\n  const bolts = param(\"bolts\", 6, { options: [4, 6, 8] });\n  const boltD = param(\"boltDiameter\", 5.5, { min: 2, max: 14, unit: mm, step: 0.1 });\n\n  // half cross-section in XZ, revolved around Z\n  const r = od / 2, rb = bore / 2, rh = rb + 8;\n  const body = sketch(plane.XZ, { tag: \"section\" })\n    .moveTo([rb, 0])\n    .lineTo([r, 0], { tag: \"bottom\" })\n    .lineTo([r, t], { tag: \"rim\" })\n    .lineTo([rh, t], { tag: \"shoulder\" })\n    .lineTo([rh, t + hub], { tag: \"hub\" })\n    .lineTo([rb, t + hub], { tag: \"top\" })\n    .close({ tag: \"bore\" })\n    .revolve(360, { axis: \"Z\", tag: \"body\" });\n\n  const drilled = body.subtract(boltCircle(bolts, (r + rh) / 2, boltD, t), { tag: \"drill\" });\n  return drilled\n    .fillet(drilled.edges(\"shoulder & hub\"), 3, { tag: \"hubFillet\" })\n    .chamfer(drilled.edges(\"rim & body.side.bottom\"), 1, { tag: \"edgeBreak\" })\n    .color(color.auto())\n    .material(\"steel\");\n});\n```\n\n## examples/gasket/studios/gasket.ts\n\n```ts\nimport { part, param, sketch, plane, mm } from \"parasocial\";\n\nexport const name = \"Gasket\";\n\nexport default part(\"Gasket\", ({ color }) => {\n  const w = param(\"width\", 70, { unit: mm });\n  const d = param(\"depth\", 40, { unit: mm });\n  const t = param(\"thickness\", 1.5, { min: 0.5, max: 4, unit: mm, step: 0.1 });\n  const s = sketch(plane.XY, { tag: \"outline\" })\n    .rect(w, d, { tag: \"edge\" })\n    .rect(w - 12, d - 12, { tag: \"window\" });\n  for (const [x, y] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) s.circle([x * (w / 2 - 3), y * (d / 2 - 3)], 1.6);\n  s.slot([-8, d / 2 - 3], [8, d / 2 - 3], 2.4, { tag: \"keyway\" });\n  return s.extrude(t, { tag: \"sheet\" }).color(color.auto()).material(\"nylon\");\n});\n```\n\n## examples/hinge/studios/box.ts\n\n```ts\nimport { part, param, box, cylinder, mm } from \"parasocial\";\n\nexport const name = \"Box\";\n\n// A box with a hinged lid on top and a drawer below. The parts are modeled closed, in place;\n// studios/mechanism.ts assembles copies of them (open it and drag the lid or the drawer).\nconst W = 70;\nconst D = 50;\nconst WALL = 2;\n\nexport default part(\"Body\", ({ color }) => {\n  const h = param(\"height\", 40, { min: 30, max: 80, unit: mm });\n  const bay = param(\"bay\", 11, { min: 6, max: 20, unit: mm, label: \"drawer height\" });\n  const floor = WALL + bay + WALL;\n  const block = box(W, D, h, { center: \"xy\", tag: \"block\" });\n  // storage on top, open to the lid\n  const well = box(W - 2 * WALL, D - 2 * WALL, h - floor + 1, { center: \"xy\", tag: \"well\" }).translate([0, 0, floor]);\n  // the drawer bay, open at the front\n  const slot = box(W - 2 * WALL, D - WALL + 1, bay, { center: \"xy\", tag: \"bay\" }).translate([0, -(WALL + 1) / 2, WALL]);\n  return block\n    .subtract(well, slot, { tag: \"hollow\" })\n    .color(color.auto())\n    .material(\"pla\")\n    // the lid turns about the back top edge (axis pointing -X, so opening is positive)\n    .connector(\"hinge\", { origin: [0, D / 2, h], axis: [-1, 0, 0] });\n});\n\nexport const lid = part(\"Lid\", ({ color }) => {\n  const h = param(\"height\", 40, { min: 30, max: 80, unit: mm });\n  const t = param(\"thickness\", 3, { min: 2, max: 6, unit: mm, step: 0.5 });\n  const plate = box(W, D, t, { center: \"xy\", tag: \"plate\" }).translate([0, 0, h]);\n  const tab = box(16, 5, t, { center: \"xy\", tag: \"tab\" }).translate([0, -D / 2 - 2.5, h]);\n  return plate.union(tab, { tag: \"lid\" }).color(color.auto()).material(\"pla\");\n});\n\nexport const drawer = part(\"Drawer\", ({ color }) => {\n  const bay = param(\"bay\", 11, { min: 6, max: 20, unit: mm, label: \"drawer height\" });\n  const gap = 0.4;\n  // the tray fills the bay less a small gap all round; its front is flush with the body\n  const tw = W - 2 * WALL - 2 * gap;\n  const td = D - WALL - gap;\n  const th = bay - 2 * gap;\n  const cy = -(WALL + gap) / 2;\n  const tray = box(tw, td, th, { center: \"xy\", tag: \"tray\" }).translate([0, cy, WALL + gap]);\n  const inside = box(tw - 3, td - 3, th, { center: \"xy\", tag: \"inside\" }).translate([0, cy, WALL + gap + 1.5]);\n  // the front panel covers the bay opening, touching the body's front face\n  const front = box(W, 3, bay + 2, { center: \"xy\", tag: \"front\" }).translate([0, -D / 2 - 1.5, WALL - 1]);\n  const knob = cylinder(4, 6, { at: [0, -D / 2 - 3, WALL + bay / 2], axis: [0, -1, 0], tag: \"knob\" });\n  return tray\n    .subtract(inside, { tag: \"hollow\" })\n    .union(front, knob, { tag: \"drawer\" })\n    .color(color.auto())\n    .material(\"pla\")\n    // slides straight out the front\n    .connector(\"rail\", { origin: [0, -D / 2, WALL + bay / 2], axis: [0, -1, 0] });\n});\n```\n\n## examples/hinge/studios/mechanism.ts\n\n```ts\nimport { assembly } from \"parasocial\";\nimport body, { lid, drawer } from \"./box\";\n\nexport const name = \"Mechanism\";\n\n// How the box's parts move, on this studio's own copies of them. Every joint is 0 where the parts\n// are modeled (closed); drag the lid or the drawer. Copies that run into each other show red.\nexport default assembly(\"Hinged box\", ({ revolute, slider }) => {\n  revolute(body, lid, body.at(\"hinge\"), { min: 0, max: 110, name: \"lid\" });\n  slider(body, drawer, drawer.at(\"rail\"), { min: 0, max: 40, name: \"drawer\" });\n});\n```\n\n## examples/knob/studios/knob.ts\n\n```ts\nimport { part, param, sketch, plane, cylinder, mm } from \"parasocial\";\n\nexport const name = \"Knob\";\n\nexport default part(\"Knob\", ({ color }) => {\n  const d = param(\"diameter\", 30, { min: 12, max: 80, unit: mm });\n  const h = param(\"height\", 16, { min: 6, max: 40, unit: mm });\n  const grips = param(\"grips\", 18, { min: 6, max: 40, step: 1 });\n  const shaft = param(\"shaft\", 6, { min: 3, max: 10, unit: mm, step: 0.1 });\n\n  const puck = sketch(plane.XY).circle([0, 0], d / 2, { tag: \"rim\" }).extrude(h, { tag: \"body\" });\n  const body = puck.fillet(puck.edges(\"body.cap.end & rim\"), 1.5, { tag: \"topRound\" });\n  const groove = cylinder(1.2, h + 2, { at: [d / 2 + 0.4, 0, -1], tag: \"groove\" }).circularPattern(grips, { tag: \"grooves\" });\n  const knurled = body.subtract(groove, { tag: \"knurl\" });\n  const dShaft = sketch(plane.XY)\n    .moveTo([-shaft / 2, 0])\n    .threePointArc([0, -shaft / 2], [shaft / 2, 0], { tag: \"round\" })\n    .lineTo([shaft / 2, shaft * 0.3], { tag: \"flatSide\" })\n    .lineTo([-shaft / 2, shaft * 0.3], { tag: \"flat\" })\n    .close()\n    .extrude(h * 0.7, { tag: \"shaftHole\" });\n  return knurled.subtract(dShaft, { tag: \"socket\" }).color(color.auto());\n});\n```\n\n## examples/lamp/studios/lamp.ts\n\n```ts\nimport { part, param, sketch, cylinder, plane, mm, type P2, type Solid } from \"parasocial\";\n\nexport const name = \"Lamp\";\n\n// An articulated desk lamp. Two parallelogram linkages (an arm plus a thinner rod, pinned to\n// knuckles at both ends) keep the elbow knuckle and the wrist level wherever the arms go, so\n// the shade keeps pointing where it was aimed. Parts are modeled in place at their home pose and\n// stay put; studios/mechanism.ts assembles copies of them (drag the arms, shade or turntable).\n//\n// Side view: x forward, z up; every pivot axis runs along Y. The knuckles (turret fin, elbow,\n// wrist) are thin fins on the center plane; the arms ride on one side of them, the rods on the\n// other, so the two halves of each parallelogram never meet.\n\n// ---------- layout ----------\nconst BASE_H = 18;\nconst GAP = 0.5; // under the turntable\nconst FIN = 4; // knuckle fins: |y| <= FIN\nconst LINK = [4.6, 10.6] as const; // links ride in this y band (either side)\nconst CAP = [11.2, 13.2] as const; // pivot caps outside the links\nconst PIN_R = 3.5;\nconst HOLE_R = 3.8; // 0.3 mm running clearance on the pins\n\nconst pt = (p: P2, d: P2): P2 => [p[0] + d[0], p[1] + d[1]];\nconst polar = (p: P2, len: number, deg: number): P2 => pt(p, [len * Math.cos((deg * Math.PI) / 180), len * Math.sin((deg * Math.PI) / 180)]);\n\n/**\n * The linkage layout, as (x, z) pivots; arms pivot on +y, rods on -y. The arm lengths are shared\n * params: every part that touches a loop reads the same value, so the loops close at any length.\n * Home pose: the lower arm at 62° up, the upper arm at 12° down.\n */\nfunction layout() {\n  const lower = param(\"lowerArm\", 210, { min: 180, max: 240, unit: mm, shared: true, label: \"lower arm\" });\n  const upper = param(\"upperArm\", 200, { min: 170, max: 230, unit: mm, shared: true, label: \"upper arm\" });\n  const A0: P2 = [0, 120]; // shoulder: lower arm on the turret\n  const B0: P2 = pt(A0, [-26, 0]); // shoulder: lower rod\n  const A1: P2 = polar(A0, lower, 62); // elbow: lower arm\n  const B1: P2 = polar(B0, lower, 62); // elbow: lower rod\n  const C0: P2 = pt(A1, [10, 34]); // elbow: upper arm\n  const D0: P2 = pt(C0, [0, -26]); // elbow: upper rod\n  const C1: P2 = polar(C0, upper, -12); // wrist: upper arm\n  const D1: P2 = polar(D0, upper, -12); // wrist: upper rod\n  const H: P2 = pt(C1, [40, -14]); // wrist: shade tilt\n  const SHADE: P2 = pt(H, [0, -46]); // shade's socket plane, on the shade axis\n  return { A0, B0, A1, B1, C0, D0, C1, D1, H, SHADE };\n}\n\n/** A frame on a pivot: axis along -Y, so positive angles swing counterclockwise in side view (arms up). */\nconst pivot = (p: P2) => ({ origin: [p[0], 0, p[1]] as [number, number, number], axis: [0, -1, 0] as [number, number, number], x: \"X\" as const });\n\n// ---------- helpers ----------\n\n/** Convex outline of `pts` grown by `r` (rounded), with `holes`, as a plate from y0 to y1. */\nfunction plate(pts: P2[], r: number, y0: number, y1: number, holes: P2[], tag: string): Solid {\n  const sk = sketch(plane.XZ.offset(-y1), { tag: `${tag}Sketch` });\n  if (pts.length === 2) sk.slot(pts[0], pts[1], 2 * r, { tag: \"outline\" });\n  else {\n    const h = hull(pts);\n    const n = h.length;\n    const normal = (i: number): P2 => {\n      const a = h[i], b = h[(i + 1) % n];\n      const l = Math.hypot(b[0] - a[0], b[1] - a[1]);\n      return [(b[1] - a[1]) / l, -(b[0] - a[0]) / l]; // outward for a CCW hull\n    };\n    for (let i = 0; i < n; i++) {\n      const a = h[i], b = h[(i + 1) % n], ni = normal(i), nj = normal((i + 1) % n);\n      const s: P2 = [a[0] + r * ni[0], a[1] + r * ni[1]];\n      if (i === 0) sk.moveTo(s);\n      sk.lineTo([b[0] + r * ni[0], b[1] + r * ni[1]], { tag: `side${i + 1}` });\n      const m = [ni[0] + nj[0], ni[1] + nj[1]];\n      const ml = Math.hypot(m[0], m[1]);\n      const end: P2 = [b[0] + r * nj[0], b[1] + r * nj[1]];\n      sk.threePointArc([b[0] + (r * m[0]) / ml, b[1] + (r * m[1]) / ml], end, { tag: `round${i + 1}` });\n    }\n    sk.close();\n  }\n  holes.forEach((p, i) => sk.circle(p, HOLE_R, { tag: `hole${i + 1}` }));\n  return sk.extrude(y1 - y0, { tag });\n}\n\n/** Counterclockwise convex hull (x, z). */\nfunction hull(pts: P2[]): P2[] {\n  const p = [...pts].sort((a, b) => a[0] - b[0] || a[1] - b[1]);\n  const cross = (o: P2, a: P2, b: P2) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);\n  const lower: P2[] = [], upper: P2[] = [];\n  for (const q of p) {\n    while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], q) <= 0) lower.pop();\n    lower.push(q);\n  }\n  for (const q of [...p].reverse()) {\n    while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], q) <= 0) upper.pop();\n    upper.push(q);\n  }\n  return [...lower.slice(0, -1), ...upper.slice(0, -1)];\n}\n\n/** A link (arm or rod) between two pivots on one side, with pin holes; its rim chamfered. */\nfunction link(a: P2, b: P2, width: number, side: 1 | -1, tag: string): Solid {\n  const [y0, y1] = side > 0 ? LINK : [-LINK[1], -LINK[0]];\n  const bar = plate([a, b], width / 2, y0, y1, [a, b], tag);\n  return bar.chamfer(bar.edges(`${tag}.cap & outline`), 0.8, { tag: `${tag}Edge` });\n}\n\n/** A knuckle fin through `pts` (the center plane), with a pin and cap at each pivot on its side. */\nfunction knuckle(pts: P2[], pins: [P2, 1 | -1][], r: number, tag: string): Solid {\n  let fin = plate(pts, r, -FIN, FIN, [], tag);\n  fin = fin.chamfer(fin.edges(`${tag}.cap`), 1, { tag: `${tag}Edge` });\n  const parts = pins.map(([p, side], i) => {\n    const axis: [number, number, number] = [0, side, 0];\n    const shaft = cylinder(PIN_R, CAP[0] - FIN + 1, { at: [p[0], side * (FIN - 1), p[1]], axis, tag: `${tag}Pin${i + 1}` });\n    const cap = cylinder(6.5, CAP[1] - CAP[0], { at: [p[0], side * CAP[0], p[1]], axis, tag: `${tag}Cap${i + 1}` });\n    const c = cap.chamfer(cap.edges(\"cap.end\"), 0.8, { tag: `${tag}CapEdge${i + 1}` });\n    return shaft.union(c, { tag: `${tag}Bolt${i + 1}` });\n  });\n  return fin.union(...parts, { tag: `${tag}Pinned` });\n}\n\nconst ALU = { metalness: 0.85, roughness: 0.35 };\n\n// ---------- parts ----------\n\nexport default part(\"Base\", () => {\n  const d = param(\"diameter\", 170, { min: 140, max: 220, unit: mm });\n  const disc = sketch(plane.XY).circle([0, 0], d / 2, { tag: \"rim\" }).extrude(BASE_H, { tag: \"disc\" });\n  const rounded = disc.fillet(disc.edges(\"disc.cap.end\"), 7, { tag: \"topRound\" });\n  return rounded\n    .chamfer(rounded.edges(\"disc.cap.start\"), 1.5, { tag: \"foot\" })\n    .color(\"#26282c\")\n    .appearance({ roughness: 0.55, metalness: 0.2 })\n    .material(\"steel\");\n});\n\nexport const turret = part(\"Turret\", () => {\n  const { A0, B0 } = layout();\n  const z0 = BASE_H + GAP;\n  const ring = sketch(plane.XY.offset(z0)).circle([0, 0], 42, { tag: \"ring\" }).extrude(10, { tag: \"table\" });\n  const table = ring.chamfer(ring.edges(\"table.cap.end\"), 2, { tag: \"tableEdge\" });\n  // the tower: from the turntable up to the shoulder pivots\n  const top = z0 + 10;\n  const tower = sketch(plane.XZ.offset(-FIN), { tag: \"towerSketch\" })\n    .polyline([[-40, top - 1], [16, top - 1], [9, A0[1]], [B0[0] - 9, B0[1]]], { tag: \"stem\" })\n    .extrude(2 * FIN, { tag: \"tower\" });\n  const shoulder = knuckle([A0, B0], [[A0, 1], [B0, -1]], 12, \"shoulder\");\n  return table\n    .union(tower, shoulder, { tag: \"turret\" })\n    .color(\"#c7cbd1\")\n    .appearance(ALU)\n    .material(\"aluminum\")\n    .connector(\"swivel\", { origin: [0, 0, BASE_H], axis: \"Z\", x: \"X\" })\n    .connector(\"arm\", pivot(A0))\n    .connector(\"rod\", pivot(B0));\n});\n\nexport const lowerArm = part(\"Lower arm\", () => {\n  const { A0, A1 } = layout();\n  return link(A0, A1, 18, 1, \"lowerArm\").color(\"#d8452e\").appearance({ roughness: 0.35 }).material(\"aluminum\").connector(\"elbow\", pivot(A1));\n});\n\nexport const lowerRod = part(\"Lower rod\", () => {\n  const { B0, B1 } = layout();\n  return link(B0, B1, 11, -1, \"lowerRod\").color(\"#8b9097\").appearance(ALU).material(\"steel\").connector(\"elbow\", pivot(B1));\n});\n\nexport const elbow = part(\"Elbow\", () => {\n  const { A1, B1, C0, D0 } = layout();\n  return knuckle([A1, B1, C0, D0], [[A1, 1], [B1, -1], [C0, 1], [D0, -1]], 11, \"elbow\")\n    .color(\"#c7cbd1\")\n    .appearance(ALU)\n    .material(\"aluminum\")\n    .connector(\"arm\", pivot(C0))\n    .connector(\"rod\", pivot(D0));\n});\n\nexport const upperArm = part(\"Upper arm\", () => {\n  const { C0, C1 } = layout();\n  return link(C0, C1, 16, 1, \"upperArm\").color(\"#d8452e\").appearance({ roughness: 0.35 }).material(\"aluminum\").connector(\"wrist\", pivot(C1));\n});\n\nexport const upperRod = part(\"Upper rod\", () => {\n  const { D0, D1 } = layout();\n  return link(D0, D1, 10, -1, \"upperRod\").color(\"#8b9097\").appearance(ALU).material(\"steel\").connector(\"wrist\", pivot(D1));\n});\n\nexport const wrist = part(\"Wrist\", () => {\n  const { C1, D1, H } = layout();\n  return knuckle([C1, D1, H], [[C1, 1], [D1, -1], [H, 1]], 10, \"wrist\").color(\"#c7cbd1\").appearance(ALU).material(\"aluminum\").connector(\"tilt\", pivot(H));\n});\n\nexport const shade = part(\"Shade\", () => {\n  const { H, SHADE } = layout();\n  const d = param(\"shade\", 116, { min: 96, max: 130, unit: mm, label: \"shade diameter\" });\n  const R = d / 2;\n  // a bell, 3 mm wall, on a socket; revolved about the vertical shade axis\n  const bell = sketch(plane.XZ.at([SHADE[0], 0, SHADE[1]]), { tag: \"bellSketch\" })\n    .polyline(\n      [[0, 12], [17, 12], [17, -2], [30, -22], [R, -70], [R, -74], [R - 3, -74], [27, -26], [14, -6], [0, -6]],\n      { tag: \"profile\" },\n    )\n    .revolve(360, { tag: \"bell\" });\n  // the ear: rides on the wrist's tilt pin, +y side, and drops to the socket\n  const ear = plate([H, pt(SHADE, [0, 8])], 8, LINK[0], LINK[1], [H], \"ear\");\n  const earSoft = ear.chamfer(ear.edges(\"ear.cap & outline\"), 0.8, { tag: \"earEdge\" });\n  return bell\n    .union(earSoft, { tag: \"shade\" })\n    .color(\"#d8452e\")\n    .appearance({ roughness: 0.3 })\n    .material(\"aluminum\");\n});\n\nexport const bulb = part(\"Bulb\", () => {\n  const { SHADE } = layout();\n  // a globe under the socket, 0.3 mm below it\n  const s = sketch(plane.XZ.at([SHADE[0], 0, SHADE[1]]), { tag: \"globeSketch\" })\n    .moveTo([0, -6.3])\n    .lineTo([6, -6.3], { tag: \"neckTop\" })\n    .lineTo([6, -15], { tag: \"neck\" })\n    .threePointArc([15, -29], [0, -43], { tag: \"glass\" })\n    .close();\n  return s\n    .revolve(360, { tag: \"globe\" })\n    .color(\"#fff1c4\")\n    .appearance({ opacity: 0.9, roughness: 0.1 })\n    .material({ name: \"Glass\", density: 2.5 });\n});\n```\n\n## examples/lamp/studios/mechanism.ts\n\n```ts\nimport { assembly } from \"parasocial\";\nimport base, { turret, lowerArm, lowerRod, elbow, upperArm, upperRod, wrist, shade, bulb } from \"./lamp\";\n\nexport const name = \"Mechanism\";\n\n// How the lamp moves (this studio holds its own copies of the parts). Every joint is 0 where the parts are modeled. Two closed loops: the lower\n// arm, lower rod, turret and elbow form a parallelogram, and so do the upper arm, upper rod,\n// elbow and wrist, so the elbow and the wrist stay level. Four degrees of freedom: swivel,\n// shoulder, elbow and the shade's tilt. Drag the arms, the shade or the turret.\nexport default assembly(\"Desk lamp\", ({ fix, revolute, fastened }) => {\n  fix(base);\n  revolute(base, turret, turret.at(\"swivel\"), { min: -170, max: 170, name: \"swivel\" });\n\n  // lower parallelogram (angles: positive raises the arm)\n  revolute(turret, lowerArm, turret.at(\"arm\"), { min: -20, max: 45, name: \"shoulder\" });\n  revolute(turret, lowerRod, turret.at(\"rod\"), { name: \"shoulder rod\" });\n  revolute(lowerArm, elbow, lowerArm.at(\"elbow\"), { name: \"elbow pin\" });\n  revolute(lowerRod, elbow, lowerRod.at(\"elbow\"), { name: \"elbow rod pin\" });\n\n  // upper parallelogram\n  revolute(elbow, upperArm, elbow.at(\"arm\"), { min: -30, max: 50, name: \"elbow\" });\n  revolute(elbow, upperRod, elbow.at(\"rod\"), { name: \"elbow rod\" });\n  revolute(upperArm, wrist, upperArm.at(\"wrist\"), { name: \"wrist pin\" });\n  revolute(upperRod, wrist, upperRod.at(\"wrist\"), { name: \"wrist rod pin\" });\n\n  // the shade tilts on the wrist; the bulb rides in its socket\n  revolute(wrist, shade, wrist.at(\"tilt\"), { min: -30, max: 100, name: \"tilt\" });\n  fastened(shade, bulb, { name: \"bulb\" });\n});\n```\n\n## examples/slide/lib/dims.ts\n\n```ts\n// Shared between the parts and the assembly: the gear sizes and the screw's lead set how the\n// relations in studios/mechanism.ts turn one joint into another.\n\n/** Pitch radius of the crank's gear (mm). */\nexport const CRANK_R = 10;\n/** Pitch radius of the gear on the lead screw (mm): two crank turns per screw turn. */\nexport const GEAR_R = 20;\n/** The lead screw's lead: mm the carriage travels per turn. */\nexport const LEAD = 8;\n/** The lead screw's axis: along X at this height. */\nexport const AXIS_Z = 30;\n/** The crank's axis, above the screw so the two gears mesh. */\nexport const CRANK_Z = AXIS_Z + CRANK_R + GEAR_R;\n/** Inner faces of the end plates (±x), and their thickness. */\nexport const INNER = 62;\nexport const PLATE = 8;\n/** Carriage length along the screw. */\nexport const CARRIAGE = 30;\n```\n\n## examples/slide/studios/mechanism.ts\n\n```ts\nimport { assembly } from \"parasocial\";\nimport frame, { crank, leadScrew, carriage } from \"./slide\";\nimport { CRANK_R, GEAR_R, LEAD, INNER, CARRIAGE } from \"../lib/dims\";\n\nexport const name = \"Mechanism\";\n\n// The joints of the slide, tied together: one degree of freedom. Drag the crank, the screw or the\n// carriage and the other two follow; the carriage stops at the end plates, and so does the crank.\nexport default assembly(\"Lead-screw slide\", ({ fix, revolute, slider, gear, screw }) => {\n  fix(frame);\n  const turn = revolute(frame, crank, crank.at(\"axle\"), { name: \"crank\" });\n  const spin = revolute(frame, leadScrew, leadScrew.at(\"axis\"), { name: \"screw\" });\n  const travel = slider(frame, carriage, carriage.at(\"rail\"), { min: -(INNER - CARRIAGE / 2), max: INNER - CARRIAGE / 2, name: \"carriage\" });\n  // meshing gears turn opposite ways: the screw turns -10/20 of a turn per crank turn\n  gear(turn, spin, -CRANK_R / GEAR_R);\n  // a right-handed screw: 8 mm along +X per turn\n  screw(spin, travel, LEAD);\n});\n```\n\n## examples/slide/studios/slide.ts\n\n```ts\nimport { part, box, cylinder } from \"parasocial\";\nimport { CRANK_R, GEAR_R, AXIS_Z, CRANK_Z, INNER, PLATE, CARRIAGE } from \"../lib/dims\";\n\nexport const name = \"Slide\";\n\n// A lead-screw slide: a hand crank turns the lead screw through a pair of gears, and the screw\n// drives a carriage along it. The parts are modeled in place; studios/mechanism.ts ties their\n// joints together with gear and screw relations, so turning the crank, the screw or pushing the\n// carriage moves all three. The gears are drawn as discs at their pitch circles.\nconst HOLE = 4.5; // clearance for the 4 mm shafts\nconst GEAR_T = 6; // gear thickness, outside the left end plate\nconst GEAR_X = -INNER - PLATE - 4 - GEAR_T; // the gears' outer face\n\nexport default part(\"Frame\", ({ color }) => {\n  const base = box(2 * (INNER + PLATE) + 20, 40, 6, { center: \"xy\", tag: \"base\" });\n  const left = box(PLATE, 40, CRANK_Z + 12, { center: \"xy\", tag: \"left\" }).translate([-INNER - PLATE / 2, 0, 0]);\n  const right = box(PLATE, 40, AXIS_Z + 14, { center: \"xy\", tag: \"right\" }).translate([INNER + PLATE / 2, 0, 0]);\n  const screwHoles = cylinder(HOLE, 2 * (INNER + PLATE) + 2, { at: [0, 0, AXIS_Z], axis: \"X\", center: true, tag: \"screwHoles\" });\n  const crankHole = cylinder(HOLE, PLATE + 2, { at: [-INNER - PLATE / 2, 0, CRANK_Z], axis: \"X\", center: true, tag: \"crankHole\" });\n  return base.union(left, right, { tag: \"frame\" }).subtract(screwHoles, crankHole, { tag: \"bored\" }).color(color.auto()).material(\"aluminum\");\n});\n\nexport const crank = part(\"Crank\", ({ color }) => {\n  // the small gear, its shaft into the left plate, and a handle on the outside\n  const gear = cylinder(CRANK_R - 0.2, GEAR_T, { at: [GEAR_X, 0, CRANK_Z], axis: \"X\", tag: \"gear\" });\n  const shaft = cylinder(4, -GEAR_X - GEAR_T - INNER, { at: [GEAR_X + GEAR_T, 0, CRANK_Z], axis: \"X\", tag: \"shaft\" });\n  const handle = cylinder(3, 14, { at: [GEAR_X - 14, 0, CRANK_Z + CRANK_R - 4], axis: \"X\", tag: \"handle\" });\n  return gear\n    .union(shaft, handle, { tag: \"crank\" })\n    .color(color.auto())\n    .material(\"steel\")\n    .connector(\"axle\", { origin: [GEAR_X, 0, CRANK_Z], axis: \"X\" });\n});\n\nexport const leadScrew = part(\"Lead screw\", ({ color }) => {\n  const rod = cylinder(4, -GEAR_X + INNER + PLATE + 2, { at: [GEAR_X, 0, AXIS_Z], axis: \"X\", tag: \"rod\" });\n  const gear = cylinder(GEAR_R - 0.2, GEAR_T, { at: [GEAR_X, 0, AXIS_Z], axis: \"X\", tag: \"gear\" });\n  return rod\n    .union(gear, { tag: \"screw\" })\n    .color(color.auto())\n    .material(\"steel\")\n    .connector(\"axis\", { origin: [0, 0, AXIS_Z], axis: \"X\" });\n});\n\nexport const carriage = part(\"Carriage\", ({ color }) => {\n  const block = box(CARRIAGE, 30, 2 * (AXIS_Z - 8), { center: \"xy\", tag: \"block\" }).translate([0, 0, 8]);\n  const nut = cylinder(HOLE, CARRIAGE + 2, { at: [0, 0, AXIS_Z], axis: \"X\", center: true, tag: \"nut\" });\n  return block\n    .subtract(nut, { tag: \"carriage\" })\n    .color(color.auto())\n    .material(\"pla\")\n    .connector(\"rail\", { origin: [0, 0, AXIS_Z], axis: \"X\" });\n});\n```\n\n## examples/stage/studios/parts.ts\n\n```ts\nimport { part, param, box, std, mm, type Vec3 } from \"parasocial\";\n\nexport const name = \"Stage parts\";\n\n// A small linear stage built from standard content: an MGN12 rail and MGN12H carriage, a table\n// bolted on with ISO 4762 screws in counterbores, a 608 bearing seat, heat-set inserts and a\n// captive nut. studios/stage.ts assembles it.\nconst RAIL = 200;\nconst PLATE = 6; // base thickness: the rail sits on top\nconst CAR = std.tables.mgnCarriages.MGN12H;\nconst TABLE_Z = PLATE + CAR.H; // the table sits on the carriage\nconst BRG = std.tables.bearings[\"608\"];\n\n/** Four points at (±x, ±y) on the plane z. */\nconst corners = (x: number, y: number, z: number): Vec3[] => [-1, 1].flatMap((sx) => [-1, 1].map((sy): Vec3 => [sx * x, sy * y, z]));\n\nexport default part(\"Base\", ({ color }) => {\n  const width = param(\"width\", 40, { min: 30, max: 80, unit: mm, label: \"Width\" });\n  const plate = box(RAIL + 40, width, PLATE, { center: \"xy\", tag: \"plate\" });\n  // tapped M3 holes under the rail's bolt holes, countersunk M4 holes to mount the base\n  const railBolts = std.mgnRailHoles(\"MGN12\", RAIL).map((x): Vec3 => [x, 0, PLATE]);\n  return plate\n    .hole(railBolts, { screw: \"M3\", fit: \"tap\", depth: 5, tag: \"rail-taps\" })\n    .hole(corners(RAIL / 2 + 10, width / 2 - 7, PLATE), { screw: \"M4\", countersink: \"ISO10642\", tag: \"mount\" })\n    .color(color.auto())\n    .material(\"aluminum\");\n});\n\nexport const rail = part(\"Rail\", () => std.mgnRail(\"MGN12\", RAIL).translate([0, 0, PLATE]));\n\nexport const carriage = part(\"Carriage\", () => std.mgnCarriage(\"MGN12H\").translate([0, 0, PLATE]));\n\nexport const table = part(\"Table\", ({ color }) => {\n  const t = param(\"thickness\", 8, { min: 8, max: 14, unit: mm, label: \"Thickness\" });\n  const top = TABLE_Z + t;\n  const plate = box(90, 40, t, { center: \"xy\", tag: \"table\" }).translate([0, 0, TABLE_Z]);\n  // a 608 seat from the top, with a shoulder below it\n  const seat: Vec3 = [30, 0, top];\n  return (\n    plate\n      // counterbored screws into the carriage's C × B pattern; the \"bolt\" frames seat the screws\n      .hole(corners(CAR.C / 2, CAR.B / 2, top), { screw: \"M3\", counterbore: \"ISO4762\", connector: \"bolt\", tag: \"carriage-bolts\" })\n      .hole(seat, BRG.D, { depth: BRG.B, tag: \"bearing-seat\" })\n      .hole(seat, 12, { tag: \"shoulder\" })\n      .hole(corners(40, 14, top), { insert: \"M3x5.7\", tag: \"inserts\" })\n      // a captive M3 nut slid in from the -X end, under an M3 clamp screw\n      .nutTrap([-32, 0, top], { size: \"M3\", inset: 3, slot: [-1, 0, 0], tag: \"clamp-nut\" })\n      .hole([-32, 0, top], { screw: \"M3\", tag: \"clamp\" })\n      .color(color.auto())\n      .material(\"petg\")\n      .connector(\"seat\", { origin: [seat[0], seat[1], top - BRG.B] })\n  );\n});\n\nexport const screw = part(\"Screw\", () => std.screw(\"M3\", 8));\n\nexport const bearing = part(\"Bearing\", () => std.bearing(\"608\"));\n```\n\n## examples/stage/studios/stage.ts\n\n```ts\nimport { assembly } from \"parasocial\";\nimport base, { rail, carriage, table, screw, bearing } from \"./parts\";\n\nexport const name = \"Stage\";\n\n// The carriage slides along the rail; the table, its screws and the bearing ride with it.\n// Screws and the bearing go in connector to connector: each \"bolt\" frame of the table's\n// counterbores takes a screw's \"head\", the table's \"seat\" takes the bearing's \"back\".\nexport default assembly(\"Linear stage\", ({ fix, fastened, slider, insert }) => {\n  fix(base);\n  fastened(base, rail);\n  slider(rail, carriage, rail.at(\"carriage\"), { min: -75, max: 75, name: \"travel\" });\n  fastened(carriage, table);\n  for (let i = 0; i < 4; i++) fastened(table.at(\"bolt\", i), insert(screw, { name: `bolt ${i + 1}` }).at(\"head\"));\n  fastened(table.at(\"seat\"), bearing.at(\"back\"));\n});\n```\n";
